const item=$input.item.json;
const cfg=item.__cfg||{};
if(!cfg.static_base_id||!cfg.manus_project_id||!cfg.skill_name){throw new Error('Client config missing on record '+(item.id||'(no id)')+'. Aborting rather than submitting to the wrong client.');}
const sourceName=item['Source Name']||'';
const pdfRaw=(item['Source PDF URL']||'').trim();
const siteRaw=(item['Source Site URL']||'').trim();
const isUrl=function(s){return /^https?:\/\/\S+$/i.test(s);};
const pdfOk=isUrl(pdfRaw);
const siteOk=isUrl(siteRaw);
const sourceUrl=pdfOk?pdfRaw:(siteOk?siteRaw:'');
const sourceKind=pdfOk?'PDF':(siteOk?'web page':'');
let errNote='';
if(!sourceUrl){
  if(pdfRaw&&!pdfOk){
    errNote='Source PDF URL is filled but is not a usable link - it must start with http:// or https://. Current value: '+pdfRaw.substring(0,200);
  } else if(siteRaw&&!siteOk){
    errNote='Source Site URL is filled but is not a usable link - it must start with http:// or https://. Current value: '+siteRaw.substring(0,200);
  } else {
    errNote='Neither Source PDF URL nor Source Site URL is filled. Add one, then set Status back to Ready for eBook.';
  }
}
const existingNotes=item['Notes']||'';
const STAGE_TAG='EBOOK CREATE (skill)';
const sep='==============================';
const blockRe=new RegExp('\\n*'+sep+'\\n'+STAGE_TAG.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'[\\s\\S]*?(?=(\\n'+sep+'\\n)|$)','g');
const notesBase=existingNotes.replace(blockRe,'').trim();
return{json:{record_id:item.id||'',source_name:sourceName,topic:sourceName,source_media:sourceUrl,source_kind:sourceKind,source_error_note:errNote,notes_base:notesBase,stage_tag:STAGE_TAG,sep,client:cfg.client_name||'',has_source:!!sourceUrl,cfg}};

const d=$input.item.json;
const recordId=d.record_id||'';
const shortId=recordId?recordId.substring(0,7):'norec';
const raw=(d.source_name||'ebook').toLowerCase().replace(/[^\w\s-]/g,'').replace(/\s+/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'');
let slug=raw;
if(slug.length>40){slug=slug.substring(0,40);const cut=slug.lastIndexOf('-');if(cut>15)slug=slug.substring(0,cut);}
slug=slug.replace(/^-|-$/g,'')||'ebook';
const tz=(d.cfg&&d.cfg.timezone)||'Asia/Manila';
const genDate=$now.setZone(tz).toFormat('yyyy-MM-dd');
const subfolderName=genDate+'_'+slug+'_'+shortId;
return{json:{...d,subfolder_name:subfolderName,gen_date:genDate,short_id:shortId}};

const folderResp=$input.item.json;
const prev=$('4c. Prepare Subfolder Name').item.json;
const subFolderId=folderResp.id||'';
const driveFolderUrl=subFolderId?`https://drive.google.com/drive/folders/${subFolderId}`:'';
return{json:{...prev,sub_folder_id:subFolderId,drive_folder_url:driveFolderUrl,folder_error:subFolderId?'':'Folder creation failed: '+JSON.stringify(folderResp)}};

const resp=$input.item.json||{};
const ctx=$('6. Build Manus Message').item.json;
const cfg=ctx.cfg||{};
const rec=ctx.record_id||'(no id)';
const client=cfg.client_name||'(unknown client)';
const project=String(cfg.manus_project_id||'').trim();
const wanted=String(cfg.skill_name||'').trim();
const source='client config (Skill_Name)';
if(!project){throw new Error('No Manus project ID configured for '+client+'::ebook on record '+rec+'. Nothing submitted.');}
if(!wanted){throw new Error('No Manus skill configured for '+client+'::ebook on record '+rec+'. Nothing submitted.');}
if(resp.ok===false||!Array.isArray(resp.data)){throw new Error('skill.list failed for Manus project '+project+' on record '+rec+': '+JSON.stringify(resp).substring(0,300)+'. Nothing submitted.');}
const all=resp.data.filter(Boolean);
const norm=s=>String(s||'').trim().toLowerCase();
const projectSkills=all.filter(s=>s.owner_type==='project');
const matches=projectSkills.filter(s=>norm(s.name)===norm(wanted));
if(matches.length!==1||!matches[0].id){
  const nonProject=all.filter(s=>s.owner_type!=='project'&&norm(s.name)===norm(wanted)).map(s=>(s.owner_type||'unknown')+' '+s.id);
  let why;
  if(matches.length>1)why=matches.length+' project skills share this name ('+matches.map(s=>s.id).join(', ')+')';
  else if(nonProject.length)why='only non-project copies exist ['+nonProject.join(', ')+']; personal, team, official and app skills are not allowed';
  else why='no project skill with this name';
  throw new Error('Skill '+wanted+' ('+source+') not resolved for record '+rec+' in Manus project '+project+': '+why+'. Project skills available: '+(projectSkills.map(s=>s.name).join(', ')||'(none)')+'. Nothing submitted.');
}
const hit=matches[0];
return{json:{...ctx,manus_project_id:project,resolved_skill_id:hit.id,resolved_skill_name:hit.name||wanted,resolved_skill_owner_type:hit.owner_type,resolved_skill_source:source,skill_resolve_error:''}};

