const r=$input.item.json||{};
const ctx=$('6c. Pick Skill').item.json;
const taskId=r.task_id||(r.data&&r.data.task_id)||'';
if(!taskId||r.ok===false){throw new Error('Manus task.create failed for record '+(ctx.record_id||'(no id)')+' with skill '+ctx.resolved_skill_name+' ('+ctx.resolved_skill_owner_type+', '+ctx.resolved_skill_id+'): no task_id returned. Response: '+JSON.stringify(r).substring(0,400));}
return{json:{...ctx,manus_task_id:taskId,manus_task_url:r.task_url||('https://manus.im/app/'+taskId),manus_has_task:true,manus_error:''}};

const OUTPUT_TYPE = 'ebook';
const clients = $('0a. Load Clients').all().map(i => i.json);
const outputs = $input.all().map(i => i.json);
const out = [];
for (const c of clients) {
  const name = c['Client_Name'];
  if (!name) continue;
  if (c['Static_Enabled'] !== true) continue;
  const row = outputs.find(o => o['Key'] === name + '::' + OUTPUT_TYPE);
  if (!row) continue;
  if (row['Enabled'] !== true) continue;
  if (!c['Static_Base_ID'] || !row['Drive_Folder_ID'] || !row['Manus_Project_ID'] || !row['Skill_Name']) continue;
  out.push({ json: {
    client_name: name,
    static_base_id: c['Static_Base_ID'],
    drive_shared_drive_id: c['Drive_Shared_Drive_ID'] || '',
    brand_name: c['Brand_Name'] || name,
    timezone: c['Timezone'] || 'Asia/Manila',
    drive_folder_id: row['Drive_Folder_ID'],
    manus_project_id: row['Manus_Project_ID'],
    skill_name: row['Skill_Name'],
    skill_fallback: row['Skill_Fallback'] || ''
  }});
}
return out;

const loop = $('0d. Client Loop');
let cfg = null;
try { cfg = loop.item.json; } catch (e) { cfg = null; }
if (!cfg || !cfg.static_base_id) { throw new Error('Could not resolve client config for this iteration. Refusing to run with the wrong client.'); }
return [{ json: { ...$input.item.json, __cfg: cfg } }];

const d=$input.item.json;
const cfg=d.cfg||{};
const B='alfredaiNoteBoundary';
const TABLE_ID='tblbnlPeQbK1owFTY';
const baseId=cfg.static_base_id||'';
const recId=d.record_id||'';
const atUrl=(baseId&&recId)?('https://airtable.com/'+baseId+'/'+TABLE_ID+'/'+recId):'';
const lines=[
(cfg.brand_name||cfg.client_name||'')+' Content Engine - generated asset folder',
'',
'Brand: '+(cfg.brand_name||cfg.client_name||''),
'Content type: eBook',
'Generated: '+(d.gen_date||'')+' ('+((cfg.timezone||'Asia/Manila').split('/')[1]||'PHT')+')',
'Topic: '+(d.source_name||''),
'Source ('+(d.source_kind||'link')+'): '+(d.source_media||''),
'',
'Airtable record ID: '+recId,
'Airtable record: '+atUrl,
'Airtable base: '+baseId,
'',
'Expected file: '+(d.output_filename||''),
'Manus skill: '+(d.resolved_skill_name||''),
'Manus task ID: '+(d.manus_task_id||''),
'Manus task URL: '+(d.manus_task_url||''),
'',
'Created by the automation engine. The PDF is uploaded by Manus after this note is written, so it may appear shortly after.',
'Posted vs not-posted is tracked manually in Outputs > Posted / Pending.'
];
const note=lines.join('\n');
const meta=JSON.stringify({name:'00_INFO.txt',parents:[d.sub_folder_id],mimeType:'text/plain'});
const multipart='--'+B+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+meta+'\r\n--'+B+'\r\nContent-Type: text/plain; charset=UTF-8\r\n\r\n'+note+'\r\n--'+B+'--';
return[{json:{...d,note_multipart:multipart}}];

const ctx=$('8h. Build Folder Note').item.json;
const {note_multipart,...rest}=ctx;
return{json:rest};

let ctx;
try{ctx=$('4e. Extract Folder ID').item.json;}catch(e){ctx=$('4e. Extract Folder ID').last().json;}
const cfg=ctx.cfg||{};
const e=$input.item.json||{};
const raw=e.error;
const reason=String(typeof raw==='string'?raw:(raw&&(raw.message||raw.description))||JSON.stringify(e)).substring(0,1500);
let skill='';
try{const p=$('6c. Pick Skill').item.json;if(p&&p.resolved_skill_id)skill=p.resolved_skill_name+' ('+p.resolved_skill_owner_type+', '+p.resolved_skill_id+')';}catch(err){}
const lines=[ctx.sep,ctx.stage_tag,'Updated: '+$now.setZone(cfg.timezone||'Asia/Manila').toFormat('yyyy-MM-dd HH:mm'),'FAILED - Manus task not created; record not marked ready.','Reason: '+reason];
if(skill)lines.push('Skill: '+skill);
lines.push('Source ('+(ctx.source_kind||'link')+'): '+(ctx.source_media||''),'Drive folder: '+(ctx.drive_folder_url||''));
const notes=(ctx.notes_base?ctx.notes_base+'\n\n':'')+lines.join('\n');
return{json:{record_id:ctx.record_id,failure_reason:reason,failure_skill:skill,failure_notes:notes,cfg:cfg}};

const raw=$input.item.json||{};
const rec=raw.fields?{...raw.fields,id:raw.id}:raw;
const src=$('1c. Production Approved?').item.json;
const cfg=src.__cfg||{};
const TAG='EBOOK CREATE (skill)';
const sep='==============================';
const esc=TAG.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const re=new RegExp('\\n*'+sep+'\\n'+esc+'[\\s\\S]*?(?=(\\n'+sep+'\\n)|$)','g');
const base=String(rec['Notes']||'').replace(re,'').trim();
const ts=$now.setZone(cfg.timezone||'Asia/Manila').toFormat('yyyy-MM-dd HH:mm');
const block=[sep,TAG,ts+' - Not generated: Production_Approval not ticked. Sent back to Idea.'].join('\n');
return{json:{record_id:rec.id||src.id,notes:(base?base+'\n\n':'')+block,cfg}};

const d=$input.item.json;
const tail='

FINAL OUTPUT FORMAT (mandatory - overrides any other instruction about how to end your task output): After the upload has finished, end the task with ONE final message that contains ONLY a single JSON object - no other text before or after it and no code fences. Use exactly these keys:
{"status":"done","files":["every file name you uploaded, exactly as named in Drive"],"caption":"the full post copy or caption, or an empty string if there is none","notes":"anything the team should know, or an empty string"}
If you could not finish the job or the upload, send the same JSON object with "status":"failed" and put the reason in "notes". Never end with a question instead of this message.';
return{json:{...d,manus_message:String(d.manus_message||'')+tail}};

const TYPES=['ebook'];
const clients=$('P1. Load Clients').all().map(i=>i.json);
const outputs=$input.all().map(i=>i.json);
const seen={};
const out=[];
for(const c of clients){
  const name=c['Client_Name'];
  const base=c['Static_Base_ID'];
  if(!name||c['Static_Enabled']!==true||!base||seen[base])continue;
  if(!outputs.some(o=>TYPES.some(t=>o['Key']===name+'::'+t)))continue;
  seen[base]=true;
  out.push({json:{client_name:name,static_base_id:base,notes_stage_tag:'EBOOK CREATE (skill)'}});
}
return out;

const NOTES_FIELD='Notes';
const DEFAULT_TAG='EBOOK CREATE (skill)';
const SEP='==============================';
const esc=s=>String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const items=$input.all();
const out=[];
for(let i=0;i<items.length;i++){
  const r=items[i].json||{};
  if(!r.id)continue;
  let cfg=null;
  try{cfg=$('P2. Build Poll Config').itemMatching(i).json;}catch(e){cfg=null;}
  if(!cfg||!cfg.static_base_id)continue;
  const tag=cfg.notes_stage_tag||DEFAULT_TAG;
  const m=String(r[NOTES_FIELD]||'').match(new RegExp(esc(SEP)+'\n'+esc(tag)+'\n([^]*?)(?=\n'+esc(SEP)+'\n|$)'));
  if(!m||!/^Stage: Waiting for Manus$/m.test(m[1]))continue;
  const block=m[1];
  const g=k=>{const x=block.match(new RegExp('^'+esc(k)+': *(.*)$','m'));return x?x[1].trim():'';};
  const taskId=g('Manus Task ID');
  const folderId=g('Drive folder ID');
  if(!taskId||!folderId)continue;
  const at=Date.parse(g('Dispatched At'));
  out.push({json:{record_id:r.id,cfg,stage_tag:tag,manus_task_id:taskId,manus_task_url:g('Manus Task URL'),drive_folder_id:folderId,drive_folder_url:g('Drive folder')||('https://drive.google.com/drive/folders/'+folderId),expected_files:g('Expected files').split(',').map(s=>s.trim()).filter(Boolean),skill_line:g('Skill'),source_line:g('Source'),elapsed_min:at?Math.round((Date.now()-at)/60000):0}});
}
return out;

const TIMEOUT_MIN=120;
const KIND='ebook';
const ctx=$('P4. Parse Dispatch').item.json;
const mr=$('P5. List Messages').item.json||{};
const dr=$input.item.json||{};
const msgs=Array.isArray(mr.messages)?mr.messages:[];
let agent='',waitWhy='',errText='';
for(const m of msgs){
  if(!m)continue;
  if(!agent&&m.status_update&&m.status_update.agent_status){agent=String(m.status_update.agent_status).toLowerCase();const sd=m.status_update.status_detail||{};waitWhy=String(sd.waiting_description||sd.waiting_for_event_type||'');}
  if(!errText&&m.error_message&&m.error_message.content){errText=String(m.error_message.content).substring(0,300);}
}
const parse=s=>{const t=String(s||'').replace(/```[a-zA-Z]*/g,'').trim();const a=t.indexOf('{'),b=t.lastIndexOf('}');if(a<0||b<=a)return null;try{const o=JSON.parse(t.slice(a,b+1));return(o&&typeof o==='object'&&!Array.isArray(o)&&typeof o.status==='string'&&Array.isArray(o.files))?o:null;}catch(e){return null;}};
let result=null;
for(const m of msgs){const c=m&&m.assistant_message&&m.assistant_message.content;if(typeof c==='string'&&c.trim()){result=parse(c);if(result)break;}}
const errMsg=e=>e?String((e&&e.message)||JSON.stringify(e)).substring(0,150):'';
const files=Array.isArray(dr.files)?dr.files:[];
const names=files.map(f=>(f&&f.name)||'').filter(n=>n&&n!=='00_INFO.txt');
const cnt=re=>names.filter(n=>re.test(n)).length;
const png=cnt(/\.png$/i),pdf=cnt(/\.pdf$/i),svg=cnt(/\.svg$/i);
const exp=Array.isArray(ctx.expected_files)?ctx.expected_files:[];
const missing=exp.filter(n=>names.indexOf(n)===-1);
let driveOk=false;
if(KIND==='image')driveOk=png>=Math.max(1,exp.length);
else if(KIND==='carousel')driveOk=pdf>=1&&png>=1;
else if(KIND==='infographic')driveOk=png>=1;
else if(KIND==='ebook')driveOk=pdf>=1;
else if(KIND==='posts')driveOk=png>=3;
const driveSummary=names.length+' file(s): '+png+' PNG, '+pdf+' PDF, '+svg+' SVG'+(missing.length?'; missing by name: '+missing.join(', '):'')+(dr.error?'; Drive list failed: '+errMsg(dr.error):'');
const jsonOk=!!result&&result.status.trim().toLowerCase()==='done';
const jsonSummary=result?('status '+result.status+', '+result.files.length+' file(s) listed'+(result.notes?', notes: '+String(result.notes).substring(0,300):'')):('no parseable JSON'+(agent?' (agent status: '+agent+')':'')+(mr.error?'; listMessages failed: '+errMsg(mr.error):''));
let state='wait',reason='';
if(jsonOk&&driveOk){state='ready';}
else if(agent==='error'){state='error';reason='Manus task errored'+(errText?': '+errText:'');}
else if(agent==='waiting'){state='error';reason='Manus is waiting for input'+(waitWhy?' ('+waitWhy+')':'')+'. Answer or stop the task in Manus.';}
else if(result&&!jsonOk){state='error';reason='Manus reported status '+result.status+(result.notes?': '+String(result.notes).substring(0,300):'');}
else if(ctx.elapsed_min>=TIMEOUT_MIN){state='error';reason='Timed out after '+ctx.elapsed_min+' min ('+(result?'JSON result read':'no parseable JSON result')+', '+(driveOk?'files present':'files incomplete')+')';}
return{json:{...ctx,state,reason,drive_ok:driveOk,json_ok:jsonOk,drive_summary:driveSummary,json_summary:jsonSummary,agent_status:agent}};

const NOTES_FIELD='Notes';
const PROC='eBook Processing';
const SEP='==============================';
const esc=s=>String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const sy=$now.setZone('Australia/Sydney');
const ts=sy.toFormat('yyyy-MM-dd HH:mm')+' '+(sy.offset===660?'AEDT':'AEST')+' / '+$now.setZone('Asia/Manila').toFormat('yyyy-MM-dd HH:mm')+' PHT';
const items=$input.all();
const out=[];
for(let i=0;i<items.length;i++){
  const raw=items[i].json||{};
  const rec=raw.fields?{...raw.fields,id:raw.id}:raw;
  let ctx=null;
  try{ctx=$('P7. Evaluate').itemMatching(i).json;}catch(e){ctx=null;}
  if(!ctx||!rec.id)continue;
  const st=(rec.Status&&typeof rec.Status==='object')?rec.Status.name:rec.Status;
  const notes=String(rec[NOTES_FIELD]||'');
  const cur=notes.match(new RegExp(esc(SEP)+'\n'+esc(ctx.stage_tag)+'\n([^]*?)(?=\n'+esc(SEP)+'\n|$)'));
  if(st!==PROC||!cur||!/^Stage: Waiting for Manus$/m.test(cur[1])||cur[1].indexOf('Manus Task ID: '+ctx.manus_task_id)===-1)continue;
  const base=notes.replace(new RegExp('\n*'+esc(SEP)+'\n'+esc(ctx.stage_tag)+'\n[^]*?(?=\n'+esc(SEP)+'\n|$)','g'),'').trim();
  const lines=[SEP,ctx.stage_tag,'Updated: '+ts,ctx.state==='ready'?'Stage: Ready - Manus JSON result read and files verified in Drive':'Stage: Error - '+ctx.reason,'Skill: '+ctx.skill_line,'Source: '+ctx.source_line,'Drive folder: '+ctx.drive_folder_url,'Files in Drive: '+ctx.drive_summary,'Manus result: '+ctx.json_summary,'Run time: '+ctx.elapsed_min+' min','Manus Task ID: '+ctx.manus_task_id,'Manus Task URL: '+ctx.manus_task_url];
  out.push({json:{record_id:rec.id,cfg:ctx.cfg,state:ctx.state,drive_folder_url:ctx.drive_folder_url,final_notes:(base?base+'\n\n':'')+lines.join('\n')}});
}
return out;
